import Foundation

struct Meal {
    let name: String
    let price: Double
}

func calculateTip(bill: Double, percent: Double) -> Double {
    return bill * percent
}

let rating: Int? = 5
var percent = 0.10
if (rating ?? 3) >= 4 {
    percent = 0.20
}

let meals = [Meal(name: "Pasta", price: 24.0), Meal(name: "Steak", price: 38.5)]
for meal in meals {
    let tip = calculateTip(bill: meal.price, percent: percent)
    print("\(meal.name): tip $\(String(format: "%.2f", tip))")
}

