import SwiftUI

struct HabitCounter: View {
    @State private var count = 0
    let habit = "Drink water"

    var body: some View {
        VStack(spacing: 16) {
            Text(habit)
                .font(.title)
            Text("\(count) today")
                .font(.largeTitle)
            Button("Done!") {
                count += 1
            }
            .buttonStyle(.borderedProminent)
        }
        .padding()
    }
}

